Translate("esES", "scarlet-monastery", {
	title = "Monasterio Escarlata",
	sections = {
		{
			title = "Resumen",
			text = [=[El Monasterio Escarlata se alza en las alturas del nordeste de los {link:tirisfal-glades}Claros de Tirisfal{/link}, una gran casa de piedra gris tras altos muros. Fue en otro tiempo un lugar de estudio y oración, donde el clero de {link:lordaeron}Lordaeron{/link} guardaba sus libros y formaba a jóvenes paladines en los caminos de la {link:holy-light}Luz Sagrada{/link}. Ahora es la fortaleza y el corazón palpitante de la {link:scarlet-crusade}Cruzada Escarlata{/link}. Sus campanas aún suenan. Sus salas están llenas de cruzados vestidos de rojo, y nadie que entre sin el tabardo de la Cruzada es bienvenido.]=],
		},
		{
			title = "Orígenes",
			text = [=[Ninguna crónica registra el año en que se fundó el Monasterio. Antes de la peste, se contaba entre las sedes más orgullosas de la fe de {link:lordaeron}Lordaeron{/link}, un bastión del saber oculto en los claros. Los eruditos acudían a su biblioteca. Los paladines en formación estudiaban en sus salas. Cuando la {link:third-war}Tercera Guerra{/link} trajo la {link:scourge}Plaga{/link} y la {link:fall-of-lordaeron}caída de Lordaeron{/link}, los fanáticos de la Cruzada se apoderaron del Monasterio y lo convirtieron en una fortaleza. Creen que cualquier forastero puede llevar la peste, y tratan como enemiga a toda raza que no sea la suya.]=],
		},
		{
			title = "El presente",
			text = [=[El Monasterio es el principal bastión de la Cruzada en {link:tirisfal-glades}Tirisfal{/link}. Desde aquí envía sus patrullas y mensajeros a las torres de los claros, y hace la guerra a los {link:forsaken}Renegados{/link} a las puertas de su propia capital. El comandante escarlata {link:scarlet-commander-mograine}Mograine{/link} dirige su guarnición. Su verdadera señora es la alta inquisidora {link:high-inquisitor-whitemane}Whitemane{/link}, una sacerdotisa de la que se dice que alza a los caídos para que vuelvan a luchar a sus órdenes. En {link:undercity}Entrañas{/link}, {link:varimathras}Varimathras{/link} quiere muertos a Whitemane y a sus principales lugartenientes. En {link:southshore}Costasur{/link}, {link:raleigh-the-devout}Raleigh el Devoto{/link}, que sirvió aquí en otro tiempo, quiere lo mismo. Eruditos de la {link:horde}Horda{/link} y de la {link:alliance}Alianza{/link} quieren lo que queda en la biblioteca. Los Renegados quieren corazones, libros y venganza.]=],
		},
		{
			title = "Dentro del Monasterio",
			text = [=[• {b}El cementerio.{/b} Detrás del Monasterio se encuentra su camposanto. Los interrogadores de la Cruzada trabajan en sus criptas, y los muertos inquietos caminan entre las tumbas.
• {b}La biblioteca.{/b} La gran biblioteca aún guarda los viejos libros del Monasterio, custodiados por el maestro de canes de la Cruzada y su arcanista.
• {b}El arsenal.{/b} Aquí la Cruzada adiestra a sus reclutas y arma a sus guerreros, bajo la mirada de su campeón.
• {b}La catedral.{/b} En el corazón del Monasterio, {link:scarlet-commander-mograine}Mograine{/link} y {link:high-inquisitor-whitemane}Whitemane{/link} dominan el santuario de la Cruzada.]=],
		},
	},
})

Translate("esES", "scarlet-monastery-graveyard", {
	title = "Cementerio del Monasterio Escarlata",
	sections = {
		{
			title = "Resumen",
			text = [=[El cementerio del Monasterio se extiende entre tumbas y criptas derruidas. La Cruzada no deja que sus muertos descansen en paz aquí. Sus interrogadores han convertido las criptas en un lugar de tormento, donde los prisioneros {link:forsaken}Renegados{/link} sufren hasta que cuentan lo que saben, o hasta que no queda nada de ellos. Los muertos del camposanto tampoco descansan. Espíritus angustiados y fantasmas vagan entre los mausoleos, y un mago de sangre no-muerto clama por almas en la cripta más profunda. Algunos de los muertos son antiguos. Otros, como el campeón caído que camina por allí, vistieron en otro tiempo los colores de la propia Cruzada.]=],
		},
	},
})

Translate("esES", "scarlet-monastery-library", {
	title = "Biblioteca del Monasterio Escarlata",
	sections = {
		{
			title = "Resumen",
			text = [=[La biblioteca es lo que queda del antiguo saber del Monasterio. Sus estantes guardan obras de historia, saber y ritual reunidas durante largos años, y algunas son de un valor incalculable: una mitología de los titanes, un compendio de los caídos, un manual sobre los primeros días de la amenaza no-muerta, el libro de rituales de un mago. La Cruzada usa los libros para adiestrar a sus paladines contra los muertos. No deja que nadie más los lea. Los rastreadores del maestro de canes recorren los claustros exteriores, y el arcanista guarda la sala interior.]=],
		},
	},
})

Translate("esES", "scarlet-monastery-armory", {
	title = "Arsenal del Monasterio Escarlata",
	sections = {
		{
			title = "Resumen",
			text = [=[El arsenal es donde la Cruzada forja a sus soldados. Sus campos de entrenamiento resuenan con la instrucción. Mirmidones, defensores y centuriones guardan sus salas, y las armas de la Cruzada se almacenan en sus cámaras. {link:herod}Herod{/link}, el Campeón Escarlata, manda aquí, y las armas de la Cruzada son suyas para entregarlas. Es el mejor guerrero del Monasterio, y una multitud de jóvenes aprendices lo observa y espera a ser llamada. Es aquí donde la Cruzada convierte a granjeros afligidos y huérfanos en fanáticos vestidos de rojo.]=],
		},
	},
})

Translate("esES", "scarlet-monastery-cathedral", {
	title = "Catedral del Monasterio Escarlata",
	sections = {
		{
			title = "Resumen",
			text = [=[La catedral es el santuario del Monasterio y la sede de sus señores. Sus jardines y su patio están llenos de monjes, capellanes, abades y campeones de la Cruzada. Más allá, en la gran capilla, el comandante escarlata {link:scarlet-commander-mograine}Mograine{/link} aguarda ante el altar, y la alta inquisidora {link:high-inquisitor-whitemane}Whitemane{/link} aguarda detrás de él. Quienes llegan a la capilla rara vez salen de ella. Más allá todavía, en una cámara que pocos llegan a ver, mora un segundo alto inquisidor, {link:high-inquisitor-fairbanks}Fairbanks{/link}. Quien domina la catedral domina el Monasterio.]=],
		},
	},
})

Translate("esES", "high-inquisitor-whitemane", {
	title = "Alta inquisidora Whitemane",
	subtitle = "Verdadera señora del Monasterio",
	found = "La gran capilla de la Catedral del Monasterio Escarlata",
	hint = [=[Conózcala por boca de los enemigos de la Cruzada, o búsquela en la capilla de la catedral.]=],
	allegiance = "Cruzada Escarlata",
	aliases = { "Whitemane" },
	sections = {
		{
			title = "Resumen",
			text = [=[La alta inquisidora Whitemane es la verdadera señora del {link:scarlet-monastery}Monasterio Escarlata{/link}. {link:scarlet-commander-mograine}Mograine{/link} dirige a sus soldados, pero es a Whitemane a quien obedece la Cruzada en {link:tirisfal-glades}Tirisfal{/link}. Es una sacerdotisa de un poder temible. Sana a sus campeones, los escuda, sume a sus enemigos en un sueño profundo y doblega sus mentes a su voluntad. Lo más temido de todo es su dominio sobre la propia muerte. Cuando sus guerreros caen, ella los alza de nuevo para que luchen en su nombre.]=],
		},
		{
			title = "Importancia",
			text = [=[Whitemane es la cabeza de la inquisición de la Cruzada en {link:tirisfal-glades}Tirisfal{/link}. Sus inquisidores buscan la peste en todo aquel con quien se cruzan, y la encuentran allá donde miran. Bajo su mando, el Monasterio se convirtió en un lugar donde se torturaba a hombres y mujeres inocentes por no llevar el tabardo de la Cruzada. Para los {link:forsaken}Renegados{/link} es la principal enemiga a sus puertas. Para los vivos que en otro tiempo sirvieron a la Cruzada, es la prueba de lo bajo que ha caído.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Domina el Monasterio en nombre de la {link:scarlet-crusade}Cruzada Escarlata{/link}, con {link:scarlet-commander-mograine}Mograine{/link} a su lado.
• Gobierna una inquisición que trata a todo forastero como portador de la peste.
• Invoca a la Luz para castigar a sus enemigos, para sanar y para escudar.
• Alza de la muerte a su campeón caído para que vuelva a luchar.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de estos días registra la vida de Whitemane antes de la Cruzada, el año en que se convirtió en alta inquisidora, ni dónde aprendió su poder sobre los caídos.]=],
		},
	},
	chapters = {
		{
			title = "La espina más afilada",
			hint = [=[Escuche lo que el señor del terror de Entrañas quiere que se haga en Tirisfal.]=],
			text = [=[Mientras {link:sylvanas-windrunner}la Dama Oscura{/link} vigilaba al Rey Exánime en el norte, {link:varimathras}Varimathras{/link} se volvió hacia los enemigos más cercanos. Llamó a la Cruzada la espina más afilada en el costado de los {link:forsaken}Renegados{/link}, y hormigas rojas que infestan los claros. Quería a Whitemane muerta de una vez por todas, y con ella a cada uno de sus principales lugartenientes.]=],
		},
		{
			title = "El régimen demente",
			hint = "Escuche la historia del cruzado que abandonó el Monasterio.",
			text = [=[{link:raleigh-the-devout}Raleigh el Devoto{/link} sirvió una vez con orgullo en el Monasterio. Vio a sus líderes perder el contacto con la verdad. Vio torturar a inocentes en nombre de la pureza. Se marchó, y llegó a creer que la Cruzada no sanaría mientras vivieran quienes la dirigían. Whitemane fue el primer nombre que dio. Solo cuando ella hubiera caído, dijo, podría volver a encenderse la verdadera causa.]=],
		},
		{
			title = "Levántate",
			hint = "Enfréntese a la alta inquisidora en su capilla.",
			text = [=[Cuando {link:scarlet-commander-mograine}Mograine{/link} cae ante su altar, Whitemane se adelanta llena de furia, y lo llama traición. Sume a sus enemigos en el sueño. Después se arrodilla junto a su comandante e invoca a la Luz, y Mograine se levanta para luchar de nuevo a su lado.]=],
		},
	},
	mentions = {
		{ text = "Al {link:scarlet-monastery}Monasterio Escarlata{/link}" },
		{ text = "En el nombre de la Luz" },
	},
	bonds = {
		{ id = "scarlet-commander-mograine", name = "Comandante escarlata Mograine", note = "su comandante" },
		{ id = "high-inquisitor-fairbanks", name = "Alto inquisidor Fairbanks", note = "comparte su rango" },
		{ id = "varimathras", name = "Varimathras", note = "la quiere muerta" },
		{ id = "raleigh-the-devout", name = "Raleigh el Devoto", note = "sirvió una vez a sus órdenes" },
	},
})

Translate("esES", "scarlet-commander-mograine", {
	title = "Comandante escarlata Mograine",
	subtitle = "Comandante del Monasterio",
	found = "Ante el altar de la Catedral del Monasterio Escarlata",
	hint = [=[Conózcalo por boca de los enemigos de la Cruzada, o enfréntese a él ante el altar de la catedral.]=],
	allegiance = "Cruzada Escarlata",
	aliases = { "Mograine" },
	sections = {
		{
			title = "Resumen",
			text = [=[El comandante escarlata Mograine dirige la guarnición del {link:scarlet-monastery}Monasterio Escarlata{/link}, una gran hueste de guerreros entregados a la Cruzada más allá de toda razón. Es un paladín de la {link:holy-light}Luz Sagrada{/link}, con armadura de placas y feroz en la batalla. Aguarda ante el altar de la catedral con sus soldados a su alrededor, y recibe a cada forastero como a un infiel al que hay que purificar.]=],
		},
		{
			title = "Importancia",
			text = [=[Mograine es la espada del Monasterio, como {link:high-inquisitor-whitemane}Whitemane{/link} es su voluntad. Los monjes, abades y campeones de la catedral son suyos, y también la hueste que guarda sus puertas. Sus soldados no son mercenarios. Son fanáticos que creen, como él, que la peste se esconde en cada forastero, y morirán antes de ceder una sola sala. Lucha con toda la fuerza de un caballero de la Luz, la misma Luz que los paladines de {link:lordaeron}Lordaeron{/link} llevaron una vez contra la {link:scourge}Plaga{/link}. Esa fuerza sirve ahora a una orden que tortura a inocentes. Los enemigos de la Cruzada, vivos y muertos, lo nombran entre los primeros que deben caer. Para los {link:forsaken}Renegados{/link} es un fanático al que hay que abatir. Para {link:raleigh-the-devout}Raleigh el Devoto{/link}, que sirvió una vez a sus órdenes, es uno de los hombres que desviaron a la Cruzada de su camino.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Manda la guarnición del {link:scarlet-monastery}Monasterio Escarlata{/link}.
• Lucha envuelto en el aura de reprensión, y golpea como un cruzado de la Luz.
• Cuando está al borde de la muerte, puede invocar a la Luz para sanarse de todas sus heridas.
• Lucha al lado de {link:high-inquisitor-whitemane}Whitemane{/link}, que puede alzarlo cuando cae.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de estos días registra el nombre de pila de Mograine, sus hazañas antes de la Cruzada, ni cómo llegó a mandar el Monasterio.]=],
		},
	},
	chapters = {
		{
			title = "Sus altos mandos",
			hint = [=[Escuche lo que el señor del terror de Entrañas quiere que se haga en Tirisfal.]=],
			text = [=[{link:varimathras}Varimathras{/link} no quería solo a {link:high-inquisitor-whitemane}Whitemane{/link}. Quería también eliminar a los líderes que la rodeaban, y nombró a Mograine el primero de ellos: un fanático al que había que abatir en su propio santuario.]=],
		},
		{
			title = "La caída del comandante",
			hint = "Escuche la historia del cruzado que abandonó el Monasterio.",
			text = [=[Para {link:raleigh-the-devout}Raleigh el Devoto{/link}, Mograine era uno de los más altos cargos de un régimen enloquecido. Mientras hombres así dominaran el Monasterio, dijo, cualquiera que se cruzara en el camino de la Cruzada estaría en peligro.]=],
		},
		{
			title = "Ante el altar",
			hint = "Enfréntese al comandante en la gran capilla de la catedral.",
			text = [=[Mograine recibe a los intrusos junto al altar y los llama infieles. Cuando cae, la alta inquisidora acude a vengarlo. No deja que siga muerto. Alzado por su mano, se levanta y vuelve a su lado.]=],
		},
	},
	mentions = {
		{ text = "Al {link:scarlet-monastery}Monasterio Escarlata{/link}" },
		{ text = "En el nombre de la Luz" },
	},
	bonds = {
		{ id = "high-inquisitor-whitemane", name = "Alta inquisidora Whitemane", note = "su señora" },
		{ id = "herod", name = "Herod", note = "campeón del Monasterio" },
		{ id = "varimathras", name = "Varimathras", note = "lo quiere muerto" },
		{ id = "raleigh-the-devout", name = "Raleigh el Devoto", note = "lo quiere muerto" },
	},
})

Translate("esES", "herod", {
	title = "Herod",
	subtitle = "El Campeón Escarlata",
