	hint = [=[Busque al campeón de la Cruzada en el arsenal del Monasterio.]=],
	allegiance = "Cruzada Escarlata",
	sections = {
		{
			title = "Resumen",
			text = [=[Herod es el Campeón Escarlata, el guerrero más poderoso del {link:scarlet-monastery}Monasterio Escarlata{/link}. Manda en su arsenal, donde la Cruzada adiestra y arma a sus soldados. Es un gigante con armadura de placas que lucha con una gran hacha. Gira entre sus enemigos en una tormenta de filos, los arrolla con sus cargas y se vuelve más salvaje cuanto más sangra.]=],
		},
		{
			title = "Importancia",
			text = [=[Herod es el modelo de guerrero de la Cruzada. Los reclutas del arsenal se instruyen bajo su mirada y esperan su palabra. Los mirmidones, defensores y centuriones que guardan las salas del arsenal responden ante él, y es él quien decide cuáles de los jóvenes aprendices están listos para empuñar las armas de la Cruzada. Es uno de los cuatro líderes del Monasterio cuya muerte exigen tanto {link:varimathras}Varimathras{/link} como {link:raleigh-the-devout}Raleigh el Devoto{/link}. Anhela un enemigo digno, e invoca a la Luz para que le dé fuerzas mientras abate a sus enemigos.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Manda el arsenal del Monasterio y sus campos de entrenamiento.
• Gira como un torbellino entre sus enemigos, los hiende y se abalanza sobre ellos.
• En su furia se vuelve más fuerte cuanto más profundas son sus heridas.
• Cuando cae, los aprendices del arsenal acuden en tropel a vengarlo.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de estos días registra de dónde vino Herod ni cómo ganó su título.]=],
		},
	},
	chapters = {
		{
			title = "El desafío del campeón",
			hint = "Enfréntese al campeón en el arsenal del Monasterio.",
			text = [=[Herod recibe a los intrusos con alegría, porque ha esperado mucho un verdadero desafío. Se alegra de luchar. Cuando por fin muere, sus aprendices irrumpen en la sala, jóvenes e inexpertos, para terminar lo que su campeón no pudo.]=],
		},
	},
	mentions = {
		{ text = "Al {link:scarlet-monastery}Monasterio Escarlata{/link}" },
		{ text = "En el nombre de la Luz" },
	},
	bonds = {
		{ id = "scarlet-commander-mograine", name = "Comandante escarlata Mograine", note = "su comandante" },
		{ id = "high-inquisitor-whitemane", name = "Alta inquisidora Whitemane", note = "señora del Monasterio" },
	},
})

Translate("esES", "high-inquisitor-fairbanks", {
	title = "Alto inquisidor Fairbanks",
	subtitle = "El inquisidor oculto",
	found = "Una cámara oculta más allá de la capilla de la catedral",
