	sections = {
		{
			title = "Resumen",
			text = [=[El alto inquisidor Fairbanks mora en la {link:scarlet-monastery-cathedral}Catedral del Monasterio Escarlata{/link}, en una cámara más allá de la capilla donde {link:high-inquisitor-whitemane}Whitemane{/link} celebra su corte. Pocos saben que está allí. Ostenta el mismo rango que Whitemane, el título de alto inquisidor, y sin embargo es ella quien gobierna el Monasterio, y a él a quien se mantiene oculto. Está pálido como un cadáver, y su voz es la voz hueca de los muertos.]=],
		},
		{
			title = "Importancia",
			text = [=[Fairbanks es un enigma en el corazón de la Cruzada. En el Monasterio, solo {link:high-inquisitor-whitemane}Whitemane{/link} ostenta el mismo título. La Cruzada quema a los no-muertos allá donde los encuentra, y sin embargo un alto inquisidor con aspecto de muerto vive en su propio santuario. Aun así, es un sacerdote de gran habilidad. Se escuda y se sana, lanza una maldición de sangre sobre sus enemigos, los sume en el sueño y los hace huir aterrorizados.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Ostenta el rango de alto inquisidor de la Cruzada.
• Se mantiene en una cámara aparte, más allá del altar de la catedral.
• Maldice, aterroriza y duerme a sus enemigos, y sana sus propias heridas.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de estos días registra quién era Fairbanks, por qué comparte el rango de {link:high-inquisitor-whitemane}Whitemane{/link} ni por qué se le mantiene oculto del resto del Monasterio.]=],
		},
	},
	chapters = {
		{
			title = "La cámara del fondo",
			hint = "Encuentre al inquisidor que aguarda más allá de la capilla.",
			text = [=[Pasado el altar donde cayeron {link:scarlet-commander-mograine}Mograine{/link} y {link:high-inquisitor-whitemane}Whitemane{/link} hay una puerta, y tras la puerta aguarda Fairbanks. Lucha solo, sin guardias y sin la hueste que sirve a Mograine. Lo que sabe de la Cruzada, y por qué esta lo mantiene oculto, se lo guarda para sí. Quienes salen de su cámara solo se llevan más preguntas.]=],
		},
	},
	bonds = {
		{ id = "high-inquisitor-whitemane", name = "Alta inquisidora Whitemane", note = "comparte su rango" },
	},
})

