Translate("esES", "houndmaster-loksey", {
	title = "Maestro de canes Loksey",
	subtitle = "Señor de los canes escarlata",
	found = [=[Las salas exteriores de la Biblioteca del Monasterio Escarlata]=],
	hint = [=[Busque al señor de los canes de la Cruzada en las salas de la biblioteca.]=],
	allegiance = "Cruzada Escarlata",
	aliases = { "Loksey" },
	sections = {
		{
			title = "Resumen",
			text = [=[El maestro de canes Loksey adiestra a los canes de la {link:scarlet-crusade}Cruzada Escarlata{/link}. Sus bestias están criadas para seguir un rastro, y la Cruzada las usa para dar caza a sus enemigos por {link:tirisfal-glades}Tirisfal{/link}. Las mantiene cerca en las salas que hay ante la biblioteca. Cuando llegan enemigos, las suelta, y se lanza con su jauría a un frenesí.]=],
		},
		{
			title = "Importancia",
			text = [=[Loksey figura entre los cuatro principales lugartenientes del Monasterio. {link:varimathras}Varimathras{/link} lo quiere muerto junto con sus sucios chuchos, y {link:raleigh-the-devout}Raleigh el Devoto{/link} lo nombra junto a la propia {link:high-inquisitor-whitemane}Whitemane{/link}. Quien quiera llegar a la biblioteca debe pasar antes junto a sus rastreadores y su amo.]=],
		},
	},
	mentions = {
		{ text = "Al {link:scarlet-monastery}Monasterio Escarlata{/link}" },
		{ text = "En el nombre de la Luz" },
	},
	bonds = {
		{ id = "arcanist-doan", name = "Arcanista Doan", note = "guarda la biblioteca interior" },
	},
})

Translate("esES", "bloodmage-thalnos", {
	title = "Mago de sangre Thalnos",
	subtitle = "El muerto airado",
	found = "Las criptas del Cementerio del Monasterio Escarlata",
	hint = [=[Busque al mago muerto que ronda las criptas del cementerio del Monasterio.]=],
	allegiance = "Los muertos inquietos",
	aliases = { "Thalnos" },
	sections = {
		{
			title = "Resumen",
			text = [=[El mago de sangre Thalnos es un hechicero muerto que ronda las criptas del {link:scarlet-monastery-graveyard}Cementerio del Monasterio Escarlata{/link}. No sirve ni a la Cruzada ni a los {link:forsaken}Renegados{/link}. Tiene hambre de almas y de venganza, y clama que no hay descanso para los muertos airados. Lanza fuego y sombras contra los vivos, y las llamas brotan de él cuando se acercan. Los torturadores de la Cruzada trabajan a solo unas pocas salas de distancia. Si saben lo que yace en la cripta más profunda, nadie lo ha dicho.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de estos días registra quién fue Thalnos en vida, cómo murió ni de quién pretende vengarse.]=],
		},
	},
	bonds = {
		{ id = "interrogator-vishas", name = "Interrogador Vishas", note = "trabaja en el mismo cementerio" },
	},
})

Translate("esES", "interrogator-vishas", {
	title = "Interrogador Vishas",
	subtitle = "Torturador de la Cruzada",
	found = "La cámara de tortura del Cementerio del Monasterio Escarlata",
	hint = [=[Busque al interrogador de la Cruzada en las criptas del cementerio.]=],
	allegiance = "Cruzada Escarlata",
	aliases = { "Vishas" },
	sections = {
		{
			title = "Resumen",
			text = [=[El interrogador Vishas tortura a los prisioneros de la Cruzada en las criptas del {link:scarlet-monastery-graveyard}Cementerio del Monasterio Escarlata{/link}. Quiere todos los secretos, y los arranca con fuego y dolor. Está orgulloso de su trabajo, y orgulloso de su esposa, Nancy, que vive junto al Lago Lordamere. Le regaló un anillo de bodas que había quitado a una de sus víctimas.]=],
		},
	},
	chapters = {
		{
			title = "El anillo robado",
			hint = [=[Escuche el último deseo de un Renegado moribundo en el cementerio.]=],
			text = [=[{link:vorrel-sengutz}Vorrel Sengutz{/link} había soportado semanas de tormento a manos de Vishas. Cuando el interrogador cayó, Vorrel se alegró. Le quedaba un deseo: que la esposa de Vishas pagara por lo que había hecho su marido, y que su anillo volviera a casa, con su propia esposa, en {link:tarren-mill}Molino Tarren{/link}.]=],
		},
	},
	mentions = {
		{ text = "La venganza de {link:vorrel-sengutz}Vorrel{/link}" },
	},
	bonds = {
		{ id = "vorrel-sengutz", name = "Vorrel Sengutz", note = "su víctima" },
	},
})

Translate("esES", "vorrel-sengutz", {
	title = "Vorrel Sengutz",
	subtitle = "Prisionero del cementerio",
	found = "Las criptas del Cementerio del Monasterio Escarlata",
	hint = [=[Busque a un Renegado destrozado entre los prisioneros de la Cruzada en el cementerio.]=],
	allegiance = "Renegados",
	aliases = { "Vorrel" },
	sections = {
		{
			title = "Resumen",
			text = [=[Vorrel Sengutz es uno de los {link:forsaken}Renegados{/link}, un muerto que despertó dueño de su voluntad y sirvió a {link:sylvanas-windrunner}la Dama Oscura{/link}. La Cruzada lo capturó. El interrogador {link:interrogator-vishas}Vishas{/link} lo torturó durante semanas y le robó su anillo de bodas. Ahora Vorrel yace destrozado en el cementerio. Sabe que su tiempo en el mundo se acaba. Solo quiere venganza, y quiere que su anillo vuelva a su esposa, Monika, en {link:tarren-mill}Molino Tarren{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Su último deseo",
			hint = "Escuche el deseo del prisionero moribundo.",
			text = [=[{link:interrogator-vishas}Vishas{/link} se había jactado de su esposa, Nancy, que vivía junto al Lago Lordamere. Vorrel pidió que la encontraran y la mataran, y que llevaran su anillo a Monika. Cuando Vishas cayó, Vorrel dijo que el torturador había recibido lo que merecía.]=],
		},
	},
	mentions = {
		{ text = "La venganza de Vorrel" },
	},
	bonds = {
		{ id = "interrogator-vishas", name = "Interrogador Vishas", note = "su torturador" },
	},
})

Translate("esES", "azshir-the-sleepless", {
	title = "Azshir el Insomne",
	subtitle = "Errante del cementerio",
	found = "Vagando por el Cementerio del Monasterio Escarlata",
