	allegiance = "Los muertos inquietos",
	aliases = { "Azshir" },
	sections = {
		{
			title = "Resumen",
			text = [=[Azshir el Insomne es un espíritu oscuro que vaga por el {link:scarlet-monastery-graveyard}Cementerio del Monasterio Escarlata{/link}. No se queda en un solo lugar, y no descansa. Absorbe las almas de los vivos, los golpea con el terror y llama a los muertos de las tumbas para que luchen por él. Rara vez se le ve. Comparte el cementerio con los demás muertos inquietos, a solo unas pocas salas de donde los torturadores de la Cruzada ejercen su oficio. Su nombre es casi todo lo que los vivos saben de él.]=],
		},
		{
			title = "Sin registro",
